69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a city that
76	     *  already has this many owners is rejected with 409 Conflict. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created on a single day (by registration date); creating
80	     *  an owner once this many owners already carry today's registration date is rejected with
81	     *  429 Too Many Requests. */
82	    private static final int MAX_OWNERS_PER_DAY = 100;
83	
84	    /** When more than this many owners already carry today's registration date at creation time, the
85	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
89	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    private final TelephoneNormalizer telephoneNormalizer;
105	
106	    private final HouseholdNormalizer householdNormalizer;
107	
108	    private final AddressNormalizer addressNormalizer;
109	
110	    private final EmailNormalizer emailNormalizer;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 HouseholdNormalizer householdNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 EmailNormalizer emailNormalizer) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.householdNormalizer = householdNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.emailNormalizer = emailNormalizer;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        normalizeOwnerFields(owner);
161	        // Enforce the pre-persistence policies that can reject the new owner outright.
162	        rejectDisallowedOwnerCreation(owner);
163	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
164	        // function of last name and postcode), reject a household duplicate unless the request
165	        // declares it shares the household, and record the household size. This runs before the
166	        // identity-key check so that check sees the owner's household id.
167	        boolean declaredHouseholdMember =
168	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
169	        // Reject the create when the owner's whole derived identity key (normalized telephone,
170	        // email and household id) already matches an existing owner. This single rule subsumes the
171	        // former separate telephone, email and household duplicate checks.
172	        rejectWhenIdentityInUse(owner);
173	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
174	        // shares an existing owner's last name and postcode with a different telephone. A declared
175	        // household member is never flagged: it is a known member, not a suspected duplicate.
176	        assignPossibleDuplicate(owner, declaredHouseholdMember);
177	        // Assign the remaining create-time derived fields (namesake count, customer code,
178	        // membership number and bulk-signup warning), each fixed at creation time.
179	        assignDerivedFields(owner);
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        // Emit an audit line for the successful create, carrying the owner id, customer code,
183	        // registration date, membership level and membership number so the create can be traced
184	        // from the dedicated AUDIT log.
185	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
187	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
192	
193	    /**
194	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
195	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
196	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
197	     * the sequence of create-time rejections stays readable and a new rule is added as one more
198	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
199	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
200	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
201	     * the household id has been resolved, because that key includes the household id.
202	     *
203	     * @param owner the newly mapped and normalized owner being created
204	     */
205	    private void rejectDisallowedOwnerCreation(Owner owner) {
206	        rejectWhenDailyLimitReached(owner);
207	        rejectWhenCityAtCapacity(owner);
208	    }
209	
210	    /**
211	     * Applies the household-membership rules for a newly normalized owner being created. The
212	     * household id is a deterministic function of the owner's last name and postcode, so owners
213	     * with the same last name and postcode share it automatically; it is assigned to the new owner
214	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
215	     * same last name and postcode is a member of the same household: a second such owner is rejected
216	     * as a household duplicate (409) unless the request declares it shares the household via
217	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
218	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
219	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
220	     * is resolved here before {@link #rejectWhenIdentityInUse}.
221	     *
222	     * @param owner           the newly mapped and normalized owner being created
223	     * @param sharesHousehold whether the request declared that the owner shares an existing household
224	     * @return {@code true} if the owner joined an existing household as a declared member
225	     */
226	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
227	        // Assign the deterministic household id (a pure function of last name and postcode) so every
228	        // owner with the same last name and postcode shares it automatically.
229	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
230	        // Identify any existing owners in the same household (same computed household id).
231	        List<Owner> householdMembers = sameHouseholdOwners(owner);
232	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
233	        // the request declares it shares the household, in which case create it as a declared member.
234	        boolean declaredHouseholdMember = false;
235	        if (!householdMembers.isEmpty()) {
236	            if (!sharesHousehold) {
237	                throw new HouseholdDuplicateException(
238	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
239	            }
240	            declaredHouseholdMember = true;
241	        }
242	        // Record the size of this owner's household after this create, fixed at creation time.
243	        owner.setHouseholdSize(householdMembers.size() + 1);
244	        return declaredHouseholdMember;
245	    }
246	
247	    /**
248	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
249	     * has already been resolved: the namesake count, the per-city customer code, the membership
250	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
251	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
252	     * here keeps {@link #addOwner} focused on the high-level create sequence.
253	     *
254	     * @param owner the owner being created, already normalized and with its household resolved
255	     */
256	    private void assignDerivedFields(Owner owner) {
257	        // Record how many existing owners already share this owner's first and last name
258	        // (compared case-insensitively) before this create, fixed at creation time.
259	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
260	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
261	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
262	        // time.
263	        owner.setCustomerCode(customerCode(owner));
264	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
265	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
266	        // creation time.
267	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
268	        // Flag the create when more than 80 owners have already been created on this owner's
269	        // (adjusted business-day) registration date, fixed at creation time.
270	        owner.setBulkSignupWarning(
271	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
272	    }
273	
274	    /**
275	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
276	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
277	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
278	     * the former separate telephone, email and household duplicate checks: two owners collide only
279	     * when their whole keys are equal, and members of one household with different telephones have
280	     * different keys and are both allowed.
281	     *
282	     * @param owner the owner being created, already normalized and with its household resolved
283	     */
284	    private void rejectWhenIdentityInUse(Owner owner) {
285	        String identityKey = owner.getIdentityKey();
286	        boolean inUse = existingOwners()
287	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
288	        if (inUse) {
289	            throw new DuplicateIdentityException(
290	                "An owner with identity key " + identityKey + " already exists");
291	        }
292	    }
293	
294	    /**
295	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
296	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
297	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
298	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
299	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
300	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
301	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
302	     * possible duplicate. A declared household member is never flagged: it is a known member of the
303	     * household, not a suspected duplicate. Both values are fixed at creation time.
304	     *
305	     * @param owner                   the owner being created, already normalized and confirmed not a
306	     *                                hard duplicate
307	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
308	     *                                member
309	     */
310	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
311	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
312	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
313	            .map(Owner::getId)
314	            .min(Integer::compareTo)
315	            .orElse(null);
316	        owner.setPossibleDuplicate(matchId != null);
317	        owner.setPossibleDuplicateOf(matchId);
318	    }
319	
320	    /**
321	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
322	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
323	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
324	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
325	     *
326	     * @param existing an existing owner to compare against
327	     * @param owner    the owner being created
328	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
329	     */
330	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
331	        return existing.getPostcode() != null
332	            && existing.getPostcode().equals(owner.getPostcode())
333	            && existing.getLastName() != null
334	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
335	            && existing.getTelephone() != null
336	            && !existing.getTelephone().equals(owner.getTelephone());
337	    }
338	
339	    /**
340	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
341	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
342	     *
343	     * @param owner the owner being created
344	     */
345	    private void rejectWhenDailyLimitReached(Owner owner) {
346	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
347	            throw new DailyOwnerLimitExceededException(
348	                "The maximum number of owners that may be created today has already been reached");
349	        }
350	    }
351	
352	    /**
353	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
354	     * or more owners, with 409 Conflict.
355	     *
356	     * @param owner the owner being created
357	     */
358	    private void rejectWhenCityAtCapacity(Owner owner) {
359	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
360	            throw new CityCapacityExceededException(
361	                "The city " + owner.getCity() + " already contains the maximum number of owners");
362	        }
363	    }
364	
365	    /**
366	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
367	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
368	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
369	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
370	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
371	     * server's current date. Canonicalising the address here, before the household checks read it,
372	     * ensures duplicate detection and the shared household id both compare the normalized form.
373	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
374	     * duplicate, household and customer-code rules.
375	     *
376	     * @param owner the newly mapped owner to canonicalize
377	     */
378	    private void normalizeOwnerFields(Owner owner) {
379	        // Canonicalize the owner's address fields on create so the address is stored and returned in
380	        // canonical form and every later comparison (household duplicate detection and the shared
381	        // household id) uses it. A value that is blank after normalization is rejected with 400.
382	        normalizeAddressFields(owner);
383	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
384	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
385	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
386	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
387	        // Store the (already syntactically validated) email lower-cased so it is persisted and
388	        // returned in canonical form. A missing email is left untouched.
389	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
390	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
391	        // canonicalization so the comparison sees the lower-cased value.
392	        rejectDisposableEmailDomain(owner.getEmail());
393	        // Validate the optional postcode against the fixed range for the city's region. A postcode
394	        // is checked only when present (it is optional); one out of range for the city's region is
395	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
396	        // value is left unchanged.
397	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
398	        // Reject a supplied registration date that is later than the server's current date with
399	        // 400, before any defaulting or business-day adjustment, so a future date is never
400	        // persisted regardless of how the roll-forward would move it.
401	        rejectFutureRegistrationDate(owner.getRegistrationDate());
402	        // Default the registration date to the server's current date when the client did not
403	        // supply one, then roll the effective date forward to a business day so a Saturday or
404	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
405	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
406	        // date-derived field (such as the membership number's year segment) and the per-day
407	        // create-limit are computed from.
408	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
409	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
410	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
411	    }
412	
413	    /**
414	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
415	     * returned in canonical form. The owner may supply its address in either of two forms and the
416	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
417	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
418	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
419	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
420	     * stored {@code address} is composed from the normalized structured lines when present — the
421	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
422	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
423	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
424	     * here, before the household checks read it, ensures duplicate detection and the shared household
425	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
426	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
427	     *
428	     * @param owner the newly mapped owner whose address is canonicalized
429	     */
430	    private void normalizeAddressFields(Owner owner) {
431	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
432	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
433	            owner.setAddressLine1(line1);
434	            String composed = line1;
435	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
436	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
437	                owner.setAddressLine2(line2);
438	                composed = line1 + " " + line2;
439	            }
440	            owner.setAddress(composed);
441	        }
442	        else {
443	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
444	        }
445	    }
446	
447	    /**
448	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
449	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
450	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
451	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
452	     * domain part is left untouched.
453	     *
454	     * @param email the owner's canonicalized email, or {@code null} when absent
455	     */
456	    private void rejectDisposableEmailDomain(String email) {
457	        if (email == null) {
458	            return;
459	        }
460	        int at = email.lastIndexOf('@');
461	        if (at < 0) {
462	            return;
463	        }
464	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
465	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
466	            throw new DisposableEmailException(
467	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
468	        }
469	    }
470	
471	    /**
472	     * Rejects a supplied registration date that is later than the server's current date with a
473	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
474	     * accepted, and a date on or before today is left for the normal defaulting and business-day
475	     * adjustment.
476	     *
477	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
478	     */
479	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
480	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
481	            throw new InvalidRegistrationDateException(
482	                "The supplied registration date " + registrationDate + " is later than the current date");
483	        }
484	    }
485	
486	    /**
487	     * The fixed list of public holidays. A registration date that lands on one of these dates is
488	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
489	     */
490	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
491	        java.time.LocalDate.of(2026, 1, 1),
492	        java.time.LocalDate.of(2026, 1, 26),
493	        java.time.LocalDate.of(2026, 4, 25),
494	        java.time.LocalDate.of(2026, 12, 25),
495	        java.time.LocalDate.of(2026, 12, 28));
496	
497	    /**
498	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
499	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
500	     * unchanged. Applied to the effective registration date (whether supplied in the request or
501	     * defaulted to the server date) so the persisted registration date, every value derived from it
502	     * and the per-day create-limit all use the adjusted business day.
503	     *
504	     * @param date the effective registration date
505	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
506	     */
507	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
508	        java.time.LocalDate adjusted = date;
509	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
510	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
511	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
512	            adjusted = adjusted.plusDays(1);
513	        }
514	        return adjusted;
515	    }
516	
517	    /**
518	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
519	     * region derived from the owner's postcode (falling back to the city, via
520	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
521	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
522	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
523	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
524	     * distinct customer codes.
525	     *
526	     * @param owner the owner being created, already normalized
527	     * @return the formatted, de-duplicated customer code
528	     */
529	    private String customerCode(Owner owner) {
530	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
531	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
532	        String base = region + "-" + hash8;
533	        Set<String> taken = existingOwners()
534	            .map(Owner::getCustomerCode)
535	            .filter(code -> code != null)
536	            .collect(Collectors.toSet());
537	        if (!taken.contains(base)) {
538	            return base;
539	        }
540	        int n = 2;
541	        while (taken.contains(base + "-" + n)) {
542	            n++;
543	        }
544	        return base + "-" + n;
545	    }
546	
547	    /**
548	     * Streams the existing owners that the create-time rules match a new owner against. Every
549	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
550	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
551	     * own matching criterion rather than on how the existing owners are retrieved.
552	     *
553	     * @return a stream over all existing owners
554	     */
555	    private Stream<Owner> existingOwners() {
556	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
557	        // new create, so the duplicate, identity and household checks (and the other create-time
558	        // scans built on this helper) ignore it.
559	        return this.clinicService.findAllOwners().stream()
560	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
561	    }
562	
563	    /**
564	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
565	     * fix the per-city sequence of an owner's customer code at creation time.
566	     *
567	     * @param city the city of the owner being created
568	     * @return the number of existing owners in a matching city
569	     */
570	    private int countOwnersInCity(String city) {
571	        return (int) existingOwners()
572	            .filter(existing -> existing.getCity() != null
573	                && existing.getCity().equalsIgnoreCase(city))
574	            .count();
575	    }
576	
577	    /**
578	     * Counts the existing owners whose registration date is the given adjusted business day. Used
579	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
580	     * owners already carry that business day as their registration date.
581	     *
582	     * @param date the adjusted business-day registration date to match
583	     * @return the number of existing owners registered on that date
584	     */
585	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
586	        return (int) existingOwners()
587	            .filter(existing -> date.equals(existing.getRegistrationDate()))
588	            .count();
589	    }
590	
591	    /**
592	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
593	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
594	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
595	     * after 1 July carries the following calendar year's fiscal year.
596	     *
597	     * @param customerCode     the owner's customer code
598	     * @param registrationDate the owner's registration date
599	     * @return the formatted membership number
600	     */
601	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
602	        return String.format("%s-M%02d",
603	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
604	    }
605	
606	    /**
607	     * Returns the existing owners in the given owner's household, i.e. those sharing its
608	     * deterministic household id (the same last name and postcode). The id is computed via
609	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
610	     * whitespace are treated as the same household. Centralising how "the same household" is matched
611	     * here keeps that definition in one place for every caller.
612	     *
613	     * @param owner the owner being created, with its household id already assigned
614	     * @return the existing owners in the owner's household (possibly empty)
615	     */
616	    private List<Owner> sameHouseholdOwners(Owner owner) {
617	        String householdId = owner.getHouseholdId();
618	        return existingOwners()
619	            .filter(existing -> householdId.equals(
620	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
621	            .toList();
622	    }
623	
624	    /**
625	     * Counts the existing owners who share the given first and last name, compared
626	     * case-insensitively. Used to fix an owner's namesake count at creation time.
627	     *
628	     * @param firstName the first name of the owner being created
629	     * @param lastName  the last name of the owner being created
630	     * @return the number of existing owners with a matching first and last name
631	     */
632	    private int countNamesakes(String firstName, String lastName) {
633	        return (int) existingOwners()
634	            .filter(existing -> existing.getFirstName() != null
635	                && existing.getFirstName().equalsIgnoreCase(firstName)
636	                && existing.getLastName() != null
637	                && existing.getLastName().equalsIgnoreCase(lastName))
638	            .count();
639	    }
640	
641	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
642	    @Override
643	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
644	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
645	        if (currentOwner == null) {
646	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
647	        }
648	        currentOwner.setAddress(ownerFieldsDto.getAddress());
649	        currentOwner.setCity(ownerFieldsDto.getCity());
650	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
651	        currentOwner.setLastName(ownerFieldsDto.getLastName());
652	        // Normalize the telephone to canonical E.164 form so it is stored and returned
653	        // consistently with create; an unformattable value is rejected with 400.
654	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
655	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
656	        this.clinicService.saveOwner(currentOwner);
657	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
658	    }
659	
660	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
661	    @Transactional
662	    @Override
663	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
664	        Owner owner = this.clinicService.findOwnerById(ownerId);
665	        if (owner == null) {
666	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
667	        }
668	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
669	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
670	        // duplicate and identity checks (see existingOwners()).
671	        owner.setDeleted(true);
672	        this.clinicService.saveOwner(owner);
673	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
674	    }
675	
676	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
677	    @Override
678	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
679	        Owner owner = this.clinicService.findOwnerById(ownerId);
680	        if (owner == null) {
681	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
682	        }
683	        HttpHeaders headers = new HttpHeaders();
684	        Pet pet = petMapper.toPet(petFieldsDto);
685	        owner.setId(ownerId);
686	        pet.setOwner(owner);
687	        pet.getType().setName(null);
688	        this.clinicService.savePet(pet);
689	        PetDto petDto = petMapper.toPetDto(pet);
690	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
691	            .buildAndExpand(pet.getId()).toUri());
692	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
693	    }
694	
695	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
696	    @Override
697	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
698	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
699	        if (currentOwner != null) {
700	            Pet currentPet = this.clinicService.findPetById(petId);
701	            if (currentPet != null) {
702	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
703	                currentPet.setName(petFieldsDto.getName());
704	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
705	                this.clinicService.savePet(currentPet);
706	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
707	            }
708	        }
709	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
710	    }
711	
712	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
713	    @Override
714	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
715	        HttpHeaders headers = new HttpHeaders();
716	        Visit visit = visitMapper.toVisit(visitFieldsDto);
717	        Pet pet = new Pet();
718	        pet.setId(petId);
719	        visit.setPet(pet);
720	        this.clinicService.saveVisit(visit);
721	        VisitDto visitDto = visitMapper.toVisitDto(visit);
722	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
723	            .buildAndExpand(visit.getId()).toUri());
724	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
725	    }
726	
727	
728	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
729	    @Override
730	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
731	        Owner owner = this.clinicService.findOwnerById(ownerId);
732	        if (owner != null) {
733	            Pet pet = owner.getPet(petId);
734	            if (pet != null) {
735	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
736	            }
737	        }
738	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
739	    }
740	}
